UPDATE att_leave_balance
SET leave_used_hours = leave_used_hours + #{hours}, updated_at = NOW()
WHERE employee_id = #{employeeId} AND year = #{year}

UPDATE att_leave_balance
SET compens_used_hours = compens_used_hours + #{hours}, updated_at = NOW()
WHERE employee_id = #{employeeId} AND year = #{year}

UPDATE att_leave_balance
SET compens_earned_hours = compens_earned_hours + #{hours}, updated_at = NOW()
WHERE employee_id = #{employeeId} AND year = #{year}

UPDATE att_leave_balance
SET leave_quota_hours = #{quotaHours}, updated_at = NOW()
WHERE employee_id = #{employeeId} AND year = #{year}
